using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool, Description("Fetches a post by ID from an external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve.")] int id,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{id}", cancellationToken);

        return JsonSerializer.Serialize(post, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional target length such as '2 sentences' or '100 words'.")] string? length = null)
    {
        var instruction = length is not null
            ? $"Summarize the following text in approximately {length}."
            : "Provide a concise summary of the following text.";

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"{instruction}\n\n{text}" }
            }
        ];
    }
}

